        mockMvc.perform(get("/books").param("title", "존재하지않는제목xyzzy"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void wildcard_characters_in_the_keyword_are_matched_literally() throws Exception {
        registerBook("Orbit 100% Guide");

        mockMvc.perform(get("/books").param("title", "100%"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1));
        mockMvc.perform(get("/books").param("title", "Orbit_Guide"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void blank_or_missing_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", "   "))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private void registerBook(String title) throws Exception {
        mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated());
    }
